from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    extracted_groups = []  # Initialize an empty list to store the extracted groups
    current_group = ""  # Initialize an empty string to store the current group

    for char in paren_string:
        if char == '(':
            current_group += char
        elif char == ')':
            current_group += char
            extracted_groups.append(current_group)
            current_group = ""

    return extracted_groups

